def largest1_bordered_square(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    left = [[0] * n for _ in range(m)]   # consecutive ones ending here, moving left
    up = [[0] * n for _ in range(m)]     # consecutive ones ending here, moving up
    for i in range(m):
        for j in range(n):
            if grid[i][j]:
                left[i][j] = left[i][j - 1] + 1 if j else 1
                up[i][j] = up[i - 1][j] + 1 if i else 1
    best = 0
    for i in range(m):
        for j in range(n):
            # (i, j) is the bottom right corner
            size = min(left[i][j], up[i][j])
            while size > best:
                if left[i - size + 1][j] >= size and up[i][j - size + 1] >= size:
                    best = size
                    break
                size -= 1
    return best * best

def shortest_beautiful_substring(s: str, k: int) -> str:
    ones = [i for i, ch in enumerate(s) if ch == "1"]
    if len(ones) < k:
        return ""
    best = None
    # each candidate spans from one '1' to the '1' that is k - 1 ones later
    for i in range(len(ones) - k + 1):
        cand = s[ones[i]:ones[i + k - 1] + 1]
        if best is None or (len(cand), cand) < (len(best), best):
            best = cand
    return best

