def maximum_minutes(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    INF = float("inf")

    def bfs(sources):
        dist = [[INF] * n for _ in range(m)]
        q = deque()
        for r, c in sources:
            dist[r][c] = 0
            q.append((r, c))
        while q:
            r, c = q.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 0 and dist[nr][nc] == INF:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
        return dist

    fire = bfs([(r, c) for r in range(m) for c in range(n) if grid[r][c] == 1])
    you = bfs([(0, 0)])
    tr, tc = m - 1, n - 1
    if you[tr][tc] == INF:
        return -1
    if fire[tr][tc] == INF:
        return 10 ** 9
    d = fire[tr][tc] - you[tr][tc]
    if d < 0:
        return -1
    # arriving together with the fire is fine only at the safehouse itself,
    # so we need a last step from a neighbor where we are strictly ahead
    for r, c in ((tr, tc - 1), (tr - 1, tc)):
        if r >= 0 and c >= 0 and you[r][c] != INF and fire[r][c] - you[r][c] > d:
            return d
    return d - 1

