def evaluate(expression: str) -> int:
    tokens = expression.replace("(", " ( ").replace(")", " ) ").split()
    pos = 0
    scopes = []  # innermost scope last

    def lookup(name):
        for scope in reversed(scopes):
            if name in scope:
                return scope[name]
        raise KeyError(name)

    def parse():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        if tok != "(":
            if tok[0] == "-" or tok[0].isdigit():
                return int(tok)
            return lookup(tok)
        op = tokens[pos]
        pos += 1
        if op in ("add", "mult"):
            a = parse()
            b = parse()
            pos += 1  # closing parenthesis
            return a + b if op == "add" else a * b
        # let: alternating names and values, then a final body expression
        scopes.append({})
        while True:
            tok = tokens[pos]
            if tok == "(" or tokens[pos + 1] == ")":
                value = parse()
                break
            pos += 1               # the variable name
            scopes[-1][tok] = parse()
        pos += 1  # closing parenthesis
        scopes.pop()
        return value

    return parse()

