def min_cost(max_time: int, edges: list[list[int]], passing_fees: list[int]) -> int:
    n = len(passing_fees)
    INF = float("inf")
    # cost[t][v]: cheapest toll to be at city v after exactly t minutes.
    cost = [[INF] * n for _ in range(max_time + 1)]
    cost[0][0] = passing_fees[0]
    for t in range(1, max_time + 1):
        row = cost[t]
        for x, y, w in edges:
            if w > t:
                continue
            before = cost[t - w]
            # The road can be driven in either direction.
            if before[x] + passing_fees[y] < row[y]:
                row[y] = before[x] + passing_fees[y]
            if before[y] + passing_fees[x] < row[x]:
                row[x] = before[y] + passing_fees[x]
    best = min(cost[t][n - 1] for t in range(max_time + 1))
    return -1 if best == INF else best

