def total_cost(costs: List[int], k: int, candidates: int) -> int:
    lo, hi = 0, len(costs) - 1
    front, back = [], []
    for _ in range(candidates):
        if lo <= hi:
            heapq.heappush(front, (costs[lo], lo)); lo += 1
    for _ in range(candidates):
        if lo <= hi:
            heapq.heappush(back, (costs[hi], hi)); hi -= 1
    total = 0
    for _ in range(k):
        # front indices are always smaller, so the front wins ties
        if back and (not front or back[0] < front[0]):
            cost, _ = heapq.heappop(back)
            if lo <= hi:
                heapq.heappush(back, (costs[hi], hi)); hi -= 1
        else:
            cost, _ = heapq.heappop(front)
            if lo <= hi:
                heapq.heappush(front, (costs[lo], lo)); lo += 1
        total += cost
    return total

