def is_scramble(s1: str, s2: str) -> bool:
    if len(s1) != len(s2):
        return False

    @lru_cache(maxsize=None)
    def check(i: int, j: int, length: int) -> bool:
        a = s1[i:i + length]
        b = s2[j:j + length]
        if a == b:
            return True
        # different letters can never be rearranged into each other
        if sorted(a) != sorted(b):
            return False
        for k in range(1, length):
            # first cut after k characters, pieces kept in order
            if check(i, j, k) and check(i + k, j + k, length - k):
                return True
            # first cut after k characters, pieces swapped
            if check(i, j + length - k, k) and check(i + k, j, length - k):
                return True
        return False

    return check(0, 0, len(s1))

