def len_of_v_diagonal(grid: List[List[int]]) -> int:
    n, m = len(grid), len(grid[0])
    dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]   # clockwise order

    def order(dr, dc):
        # visit cells so that (r + dr, c + dc) is processed before (r, c)
        rows = range(n - 1, -1, -1) if dr == 1 else range(n)
        cols = range(m - 1, -1, -1) if dc == 1 else range(m)
        return rows, cols

    # straight[d][r][c]: alternating run from (r, c) in direction d, no turn left
    straight = []
    for dr, dc in dirs:
        f = [[0] * m for _ in range(n)]
        rows, cols = order(dr, dc)
        for r in rows:
            nr = r + dr
            for c in cols:
                v = grid[r][c]
                if v == 1:
                    continue
                nc = c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                    f[r][c] = 1 + f[nr][nc]
                else:
                    f[r][c] = 1
        straight.append(f)

    # turn[d][r][c]: same, but one clockwise turn is still available
    turn = []
    for d, (dr, dc) in enumerate(dirs):
        tr, tc = dirs[(d + 1) % 4]
        after_turn = straight[(d + 1) % 4]
        f = [[0] * m for _ in range(n)]
        rows, cols = order(dr, dc)
        for r in rows:
            for c in cols:
                v = grid[r][c]
                if v == 1:
                    continue
                want = 2 - v
                best = 0
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == want:
                    best = f[nr][nc]
                nr, nc = r + tr, c + tc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == want:
                    best = max(best, after_turn[nr][nc])
                f[r][c] = 1 + best
        turn.append(f)

    answer = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] != 1:
                continue
            answer = max(answer, 1)
            for d, (dr, dc) in enumerate(dirs):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                    answer = max(answer, 1 + turn[d][nr][nc])
    return answer

