def min_cost(nums: List[int], cost: List[int]) -> int:
    pairs = sorted(zip(nums, cost))
    total_weight = sum(cost)

    # weighted median: first value where the running weight reaches half
    running = 0
    target = pairs[-1][0]
    for value, weight in pairs:
