class Codec:
    def serialize(self, root: Optional[Node]) -> str:
        if root is None:
            return ""
        tokens, stack = [], [root]
        while stack:
            node = stack.pop()
            kids = node.children or []
            tokens.append(str(node.val))
            tokens.append(str(len(kids)))      # child count fixes the shape
            stack.extend(reversed(kids))       # visit children left to right
        return " ".join(tokens)

    def deserialize(self, data: str) -> Optional[Node]:
        if not data:
            return None
        tokens = data.split()
        root = None
        stack = []   # entries are [node, children still expected]
        for i in range(0, len(tokens), 2):
            node = Node(int(tokens[i]), [])
            count = int(tokens[i + 1])
            if stack:
                parent = stack[-1]
                parent[0].children.append(node)
                parent[1] -= 1
                if parent[1] == 0:
                    stack.pop()
            else:
                root = node
            if count:
                stack.append([node, count])
        return root

