class Solution:
    def __init__(self):
        self.block = [""] * 4   # last block returned by read4
        self.size = 0           # how many characters of block are valid
        self.head = 0           # next unused character in block

    def read(self, buf: List[str], n: int) -> int:
        count = 0
        while count < n:
            if self.head == self.size:
                # internal block used up: fetch the next one
                self.size = read4(self.block)
                self.head = 0
                if self.size == 0:
                    break
            buf[count] = self.block[self.head]
            self.head += 1
            count += 1
        return count

