def maximum_profit(present: List[int], future: List[int], budget: int) -> int:
    best = [0] * (budget + 1)   # best[b]: max profit with total price at most b
    for price, worth in zip(present, future):
        gain = worth - price
        if gain <= 0 or price > budget:
            continue
        # downward so each stock is bought at most once
        for b in range(budget, price - 1, -1):
            candidate = best[b - price] + gain
            if candidate > best[b]:
                best[b] = candidate
    return best[budget]

