def diagonal_sum(mat: List[List[int]]) -> int:
    n = len(mat)
    total = 0
    for i in range(n):
        total += mat[i][i] + mat[i][n - 1 - i]
    if n % 2 == 1:
        total -= mat[n // 2][n // 2]   # the center was counted twice
    return total

def lexical_order(n: int) -> List[int]:
    result = []
    cur = 1
    for _ in range(n):
        result.append(cur)
        if cur * 10 <= n:
            cur *= 10                     # go to the first child
        else:
            # climb while there is no next sibling within range
            while cur % 10 == 9 or cur + 1 > n:
                cur //= 10
            cur += 1                      # next sibling
    return result

def min_cost(basket1: List[int], basket2: List[int]) -> int:
    balance = Counter(basket1)
    balance.subtract(basket2)   # positive: surplus in basket1, negative: in basket2

    surplus = []
    for cost, diff in balance.items():
        if diff % 2:
            return -1
        surplus.extend([cost] * (abs(diff) // 2))

    surplus.sort()
    low = min(min(basket1), min(basket2))
    swaps = len(surplus) // 2
    # each swap pays the cheaper fruit, or routes through the global minimum twice
    return sum(min(cost, 2 * low) for cost in surplus[:swaps])

