def repair_cars(ranks: List[int], cars: int) -> int:
    per_rank = Counter(ranks)   # at most 100 distinct ranks

    def can_finish(t: int) -> bool:
        done = 0
        for r, count in per_rank.items():
            done += count * math.isqrt(t // r)
            if done >= cars:
                return True
        return False

    lo, hi = 1, min(per_rank) * cars * cars
    while lo < hi:
        mid = (lo + hi) // 2
        if can_finish(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

