def earliest_acq(logs: list[list[int]], n: int) -> int:
    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:          # path compression
            parent[x], x = root, parent[x]
        return root

    groups = n
    for timestamp, x, y in sorted(logs):
        rx, ry = find(x), find(y)
        if rx != ry:
            if size[rx] < size[ry]:
                rx, ry = ry, rx
            parent[ry] = rx               # union by size
            size[rx] += size[ry]
            groups -= 1
            if groups == 1:
                return timestamp
    return -1
